teste_discriminante.conteudo:
use lg_core::{Money, RoundingMode};
use lg_tax::{tax_for, Rate};

#[test]
fn disc_l01() {
    let rate = Rate::from_ppm(50_000);
    for v in [270_i64, 250, 30, 1_050, 99_990, 1] {
        let buy = tax_for(Money::of(v, "BRL"), rate, RoundingMode::HalfEven).unwrap();
        let refund = tax_for(Money::of(-v, "BRL"), rate, RoundingMode::HalfEven).unwrap();
        assert_eq!(refund.minor(), -buy.minor(), "valor {v}");
    }
}
